# aa and ohos-aa are executables: nothing in the image links against them
# and nothing dlopen()s them, so keep the dynamic export surface down to
# the entries the toolchain requires. __cfi_check (cross-DSO CFI, ohos-aa)
# is intentionally NOT listed: it must stay an unversioned global, and lld
# synthesizes it after version script matching.
{
  global:
    _init;
    _fini;

  local:
    *;
};
